// Minimal repro: Eigen5 SVE backend has no packet_traits<double> specialization,
// so Matrix<double> code compiled with -DEIGEN_ARM64_USE_SVE falls back to
// scalar loops (Vectorizable=0), while the NEON backend vectorizes double.
#include <Eigen/Eigen>
#include <chrono>
#include <cstdio>

using namespace Eigen;

int main() {
  const int N = 300;
  MatrixXd a = MatrixXd::Random(N, N);
  MatrixXd b = MatrixXd::Random(N, N);
  volatile double sink = 0;
  auto t0 = std::chrono::steady_clock::now();
  MatrixXd c = a * b;   // GEMM uses double packets if available
  auto t1 = std::chrono::steady_clock::now();
  sink = c(0, 0);
  double ms = std::chrono::duration<double, std::milli>(t1 - t0).count();
  printf("packet_traits<double>::size = %d\n", (int)internal::packet_traits<double>::size);
#ifdef EIGEN_VECTORIZE_SVE
  printf("backend: SVE (EIGEN_VECTORIZE_SVE)\n");
#elif defined(EIGEN_VECTORIZE_NEON)
  printf("backend: NEON (EIGEN_VECTORIZE_NEON)\n");
#else
  printf("backend: none/scalar\n");
#endif
  printf("300x300 double GEMM: %.1f ms (sink=%f)\n", ms, (double)sink);
  return 0;
}

